struct rlimit pty_limits;

// Get current limit for pseudo terminals
getrlimit(RLIMIT_NPTS, &pty_limits);

rlim_t current_soft = pty_limits.rlim_cur;
rlim_t maximum_hard = pty_limits.rlim_max;


// Attempt to set a new soft limit (e.g., 50)
pty_limits.rlim_cur = 50;

// Setting requires sufficient permissions
setrlimit(RLIMIT_NPTS, &pty_limits);

